<?php
require_once __DIR__ . '/../includes/admin-functions.php';$schema=dental_schema($pdo);$labId=$schema->labId();$imageId=$schema->imageId();$imagePath=$schema->imagePath();$hasImageDate=$schema->hasCreatedAt('image_laboratoire');
$imageDate=$hasImageDate ? 'i.created_at' : 'NULL';
$imageSort=$hasImageDate ? 'i.created_at DESC,' : '';
$search=trim((string)($_GET['q']??''));$params=[];$filter='';
if($search!==''){$filter='WHERE l.nom_laboratoire LIKE ? OR l.ville LIKE ?';$params=['%'.$search.'%','%'.$search.'%'];}
$q=$pdo->prepare("SELECT i.`$imageId` id,i.`$imagePath` chemin,$imageDate created_at,l.`$labId` laboratoire_id,l.nom_laboratoire,l.ville FROM image_laboratoire i JOIN laboratoire l ON l.`$labId`=i.laboratoire_id $filter ORDER BY $imageSort i.`$imageId` DESC");$q->execute($params);$images=$q->fetchAll();
$pageTitle='Photos des laboratoires';$assetPrefix='../';$navContext='admin';$pageStyles=['assets/css/admin.css'];$pageScripts=['assets/js/admin.js'];require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/navbar.php';$flash=admin_take_flash();
?>
<main class="admin-main"><div class="admin-heading"><div><p class="admin-eyebrow">Médias</p><h1>Photos des laboratoires</h1><p class="admin-muted"><?=count($images)?> photo(s)</p></div></div><?php if($flash):?><div class="admin-alert <?=e($flash['type'])?>"><?=e($flash['message'])?></div><?php endif;?><form method="get" class="service-search admin-panel"><input type="search" name="q" value="<?=e($search)?>" placeholder="Laboratoire ou ville"><button class="admin-button admin-secondary">Rechercher</button></form><section class="photo-admin-grid"><?php foreach($images as $image):?><article class="admin-panel photo-admin-card"><a href="../<?=e($image['chemin'])?>" target="_blank" rel="noopener"><img src="../<?=e($image['chemin'])?>" alt="Photo de <?=e($image['nom_laboratoire'])?>"></a><div><strong><?=e($image['nom_laboratoire'])?></strong><span><?=e($image['ville'])?> · <?=$image['created_at'] ? e($image['created_at'] ? date('d/m/Y',strtotime($image['created_at'])) : '—') : '—'?></span><a href="laboratoires.php?id=<?=$image['laboratoire_id']?>">Ouvrir le dossier</a><form method="post" action="delete-image.php" data-confirm="Supprimer cette photo ?"><?=csrf_field()?><input type="hidden" name="image_id" value="<?=$image['id']?>"><input type="hidden" name="laboratoire_id" value="<?=$image['laboratoire_id']?>"><button class="danger-link">Supprimer</button></form></div></article><?php endforeach;?><?php if(!$images):?><div class="admin-panel empty-state">Aucune photo trouvée.</div><?php endif;?></section></main><?php require __DIR__.'/../includes/footer.php'; ?>
